const questions:Question[]=[
mc('h4-q1','hist4-l1',X('What is one advantage of a high-level language?','¿Cuál es una ventaja de un lenguaje de alto nivel?','Qual é uma vantagem de linguagem de alto nível?'),[X('Programmers can express intent with fewer machine-specific details.','Permite expresar intención con menos detalles de máquina.','Permite expressar intenção com menos detalhes da máquina.'),X('It guarantees perfect programs.','Garantiza programas perfectos.','Garante programas perfeitos.'),X('It removes the need for hardware.','Elimina la necesidad de hardware.','Elimina a necessidade de hardware.'),X('It prevents maintenance.','Impide el mantenimiento.','Impede manutenção.')],0,X('Higher-level abstractions can reduce the need to write individual machine steps.','Las abstracciones de alto nivel reducen la necesidad de escribir cada paso máquina.','Abstrações de alto nível reduzem a necessidade de escrever cada etapa da máquina.')),
tf('h4-q2','hist4-l1',X('A compiler can guarantee that source code meets user needs.','Un compilador puede garantizar que el código satisface las necesidades de usuarios.','Um compilador pode garantir que o código atende às necessidades dos usuários.'),false,X('Compilation translates code; requirements validation requires other evidence.','La compilación traduce código; validar requisitos requiere otra evidencia.','Compilação traduz código; validar requisitos exige outras evidências.')),
fill('h4-q3','hist4-l1',X('FORTRAN was designed with scientific and ______ computing in mind.','FORTRAN se diseñó pensando en computación científica y ______.','FORTRAN foi projetado para computação científica e ______.'),['numerical','numerica','numérica','numerica'],X('FORTRAN supported numerical and scientific applications.','FORTRAN apoyó aplicaciones numéricas y científicas.','FORTRAN apoiou aplicações numéricas e científicas.')),
mc('h4-q4','hist4-l2',X('What is a limitation of numbered language generations?','¿Cuál es una limitación de las generaciones numeradas?','Qual é uma limitação das gerações numeradas?'),[X('They can imply a cleaner replacement sequence than history supports.','Pueden sugerir una secuencia de reemplazo más clara de lo real.','Podem sugerir uma sequência de substituição mais clara do que ocorreu.'),X('They explain no trends at all.','No explican ninguna tendencia.','Não explicam tendência alguma.'),X('They only include assembly.','Solo incluyen ensamblador.','Incluem apenas assembly.'),X('They describe hardware only.','Solo describen hardware.','Descrevem apenas hardware.')],0,X('Generations simplify a diverse and overlapping language history.','Las generaciones simplifican una historia diversa y superpuesta.','Gerações simplificam uma história diversa e sobreposta.')),
matching('h4-q5','hist4-l3',X('Match the paradigm to its emphasis.','Relaciona el paradigma con su énfasis.','Associe o paradigma à sua ênfase.'),[X('Procedural','Procedural','Procedural'),X('Object-oriented','Orientado a objetos','Orientado a objetos'),X('Declarative','Declarativo','Declarativo')],[X('Functions or procedures transform data','Funciones transforman datos','Funções transformam dados'),X('Objects organize state and operations','Objetos organizam estado e operações','Objetos organizam estado e operações'),X('Describe a desired result','Describe un resultado deseado','Descreve um resultado desejado')],[0,1,2],X('These describe common ways to organize and express computation.','Describen formas comunes de organizar y expresar computación.','Descrevem formas comuns de organizar e expressar computação.')),
mc('h4-q6','hist4-l3',X('Can one language support multiple paradigms?','¿Puede un lenguaje admitir varios paradigmas?','Uma linguagem pode apoiar vários paradigmas?'),[X('Yes; languages often combine procedural, object-oriented, or functional features.','Sí; a menudo combinan funciones procedurales, objetos o características funcionales.','Sim; frequentemente combinam recursos procedurais, orientados a objetos ou funcionais.'),X('No; every language supports exactly one.','No; cada lenguaje admite exactamente uno.','Não; cada linguagem apoia exatamente um.'),X('Only machine code does.','Solo el código máquina.','Apenas código de máquina.'),X('Only database languages do.','Solo los lenguajes de bases de datos.','Apenas linguagens de banco de dados.')],0,X('Many modern languages are multi-paradigm.','Muchos lenguajes modernos admiten varios paradigmas.','Muitas linguagens modernas apoiam vários paradigmas.')),
tf('h4-q7','hist4-l4',X('A pure function may return different results for identical explicit inputs because the system clock changed.','Una función pura puede devolver resultados distintos para entradas iguales porque cambió el reloj.','Uma função pura pode retornar resultados diferentes para entradas iguais porque o relógio mudou.'),false,X('Reading an external clock is a hidden dependency, so the function is not pure.','Leer un reloj externo es una dependencia oculta; la función no es pura.','Ler um relógio externo é uma dependência oculta; a função não é pura.')),
fill('h4-q8','hist4-l4',X('A SQL query is commonly described as ______ because it states which rows are wanted.','Una consulta SQL suele describirse como ______ porque indica qué filas se desean.','Uma consulta SQL costuma ser descrita como ______ porque indica quais linhas são desejadas.'),['declarative','declarativo','declarativa','declarativa'],X('SQL states a result condition while the database engine chooses execution details.','SQL expresa condiciones de resultado y el motor decide detalles de ejecución.','SQL expressa condições do resultado e o mecanismo decide detalhes da execução.')),
mc('h4-q9','hist4-l5',X('What should inform a language migration decision?','¿Qué debe informar una migración de lenguaje?','O que deve orientar uma migração de linguagem?'),[X('Requirements, dependencies, cost, risks, skills, and evidence.','Requisitos, dependencias, costos, riesgos, capacidades y evidencia.','Requisitos, dependências, custos, riscos, competências e evidências.'),X('Language age alone.','Solo la antigüedad.','Apenas a idade da linguagem.'),X('Social media popularity alone.','Solo la popularidad en redes.','Apenas popularidade nas redes.'),X('No testing.','Ninguna prueba.','Nenhum teste.')],0,X('Migration is a technical and organizational decision requiring evidence.','La migración es una decisión técnica y organizativa que requiere evidencia.','Migração é uma decisão técnica e organizacional que exige evidências.')),
short('h4-q10','hist4-l5',X('Name one risk of rewriting a mature system in a new language.','Nombra un riesgo de reescribir un sistema maduro en otro lenguaje.','Cite um risco de reescrever um sistema maduro em nova linguagem.'),['regression|regresión|regressão','migration|migracion|migração','dependency|dependencia|dependência','training|capacitacion|capacitação','downtime|interrupcion|interrupção'],X('Risks can include regressions, migration complexity, dependency changes, training costs, and service disruption.','Puede haber regresiones, complejidad de migración, cambios de dependencias, capacitación o interrupciones.','Pode haver regressões, complexidade de migração, mudanças de dependências, capacitação ou interrupções.'))
];
